for w in words.split():
    for suf in ['', '.html', '.php']:
        u='http://web:5000/'+w+suf
        try:
            r=urllib.request.urlopen(u,timeout=4)
            b=r.read()
            if r.status==200 and 'flag' in b.decode('utf-8','replace').lower():
                print('FLAG-SUSPECT', u, r.status, b[:200])
            if r.status==404: pass
            else:
                print(u, r.status, len(b))
        except urllib.error.HTTPError as e:
            if e.code not in (404,405): print(u, e.code)
        except Exception as e:
            pass
print('fuzz done')
